<script setup lang="ts">
import { onMounted, onUnmounted, ref } from 'vue'

import { IonButton, IonPage, useIonRouter } from '@ionic/vue'
import { useRouter } from 'vue-router'
import VuePictureCropper, { cropper } from 'vue-picture-cropper'
import { useCreateUniverseStore } from '@/store/createUniverseStore'

const width = ref<number>(360)

const createUniverseStore = useCreateUniverseStore()
const { uploadedAvatarPreview } = createUniverseStore

const router = useRouter()
const ionRouter = useIonRouter()

onMounted(() => {
  resize()
  window.addEventListener('resize', resize)
})

onUnmounted(() => {
  window.removeEventListener('resize', resize)
})

function resize() {
  let newWidth = window.innerWidth - 32
  if (newWidth > 360) {
    newWidth = 360
  }
  width.value = newWidth
}

async function onSaveCrop() {
  if (!cropper) {
    return
  }
  const base64 = cropper.getDataURL()
  if (base64 && uploadedAvatarPreview) {
    uploadedAvatarPreview.base64 = base64

    const croppedFile = await cropper.getFile()
    if (croppedFile) {
      uploadedAvatarPreview.file = croppedFile
    }
    createUniverseStore.setUploadedAvatarPreview(uploadedAvatarPreview)
    ionRouter.back()
  }
}
function ready() {
  console.log('Cropper is ready.')
}
</script>

<template>
  <ion-page>
    <div class="w-full h-full bg-black">
      <vue-picture-cropper
        :box-style="{
          width: '100%',
          height: '100%',
          backgroundColor: '#333',
          margin: 'auto',
        }"
        :img="router.currentRoute.value.params.url as string"
        :options="{
          viewMode: 2,
          dragMode: 'crop',
          aspectRatio: 1,
        }"
        @ready="ready"
      />
      <ion-button
        fill="clear"
        class="absolute bottom-4 right-6 color-white"
        @click="onSaveCrop"
      >
        Change
      </ion-button>
      <ion-button
        fill="clear"
        class="absolute bottom-4 left-6 color-white"
        @click="() => {
          ionRouter.back();
        }"
      >
        Cancel
      </ion-button>
    </div>
  </ion-page>
</template>
